mapper.select:
SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used, response_payload, reply, success, error_msg, cost_ms, created_at
FROM agent_log
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY id ASC

    LIMIT #{limit}

SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used, reply, success, error_msg, cost_ms, created_at
FROM agent_log
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY id ASC

    LIMIT #{limit}

SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used,
       response_payload, reply, success, error_msg, cost_ms, created_at
FROM (
    SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used,
           response_payload, reply, success, error_msg, cost_ms, created_at
    FROM agent_log
    WHERE user_id = #{userId}
      AND session_id = #{sessionId}
    ORDER BY id DESC

        LIMIT #{limit}

) recent_logs
ORDER BY id ASC

SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used,
       reply, success, error_msg, cost_ms, created_at
FROM (
    SELECT id, session_id, user_id, turn, user_input, intent, slots, tools_used,
           reply, success, error_msg, cost_ms, created_at
    FROM agent_log
    WHERE user_id = #{userId}
      AND session_id = #{sessionId}
    ORDER BY id DESC

        LIMIT #{limit}

) recent_logs
ORDER BY id ASC

